INSERT INTO public.lessons (id, unit_id, title, display_order, summary, key_concepts, examples, misconceptions, status, source, is_visible)
VALUES
  ('g10-phy-waves-l1', 'g10-phy-waves-unit', 'مقدمة في الموجات', 1, 'الموجة اضطراب ينتقل ناقلًا الطاقة من مكان إلى آخر دون أن ينتقل معه وسط الانتشار نفسه. تنقسم الموجات بحسب حاجتها إلى وسط مادي: الموجات الميكانيكية (كالصوت وموجات الماء) تحتاج وسطًا لتنتقل، بينما الموجات الكهرومغناطيسية (كالضوء) تنتقل حتى في الفراغ. وتنقسم أيضًا بحسب اتجاه اهتزاز جزيئات الوسط: في الموجة الطولية يهتز الوسط في اتجاه انتشار الموجة، وفي الموجة العرضية يهتز عموديًا على اتجاه انتشارها.', ARRAY['الموجة تنقل الطاقة لا المادة', 'الموجات الميكانيكية تحتاج وسطًا ماديًا', 'الموجات الكهرومغناطيسية تنتقل في الفراغ', 'الموجة الطولية: اهتزاز موازٍ للانتشار', 'الموجة العرضية: اهتزاز عمودي على الانتشار']::text[], ARRAY['الصوت موجة ميكانيكية طولية تحتاج هواءً أو ماءً أو جسمًا صلبًا لتنتقل.', 'ضوء الشمس موجة كهرومغناطيسية تصل إلينا عبر فراغ الفضاء.', 'تموّج حبل مربوط عند هزّه لأعلى وأسفل مثال على الموجة العرضية.']::text[], ARRAY['اعتقاد أن الموجة تنقل المادة نفسها من مكان إلى آخر، والصحيح أنها تنقل الطاقة فقط.', 'اعتقاد أن كل الموجات تحتاج وسطًا، والصحيح أن الموجات الكهرومغناطيسية تنتقل في الفراغ.']::text[], 'draft', 'curriculum_seed', false),
  ('g10-phy-waves-l2', 'g10-phy-waves-unit', 'خصائص الموجة', 2, 'توصَف الموجة بعدة مقادير أساسية: الطول الموجي (λ) وهو المسافة بين قمتين متتاليتين، والتردد (f) وهو عدد الموجات المارّة بنقطة في الثانية الواحدة ويُقاس بالهرتز، والسعة وهي أقصى إزاحة عن وضع الاتزان وتدل على طاقة الموجة. وتربط هذه المقادير علاقة مهمة هي v = f λ، حيث v سرعة الموجة. فكلما زاد التردد عند ثبات السرعة قصُر الطول الموجي، والعكس صحيح.', ARRAY['الطول الموجي λ: المسافة بين قمتين متتاليتين', 'التردد f: عدد الموجات في الثانية (هرتز)', 'السعة: أقصى إزاحة عن وضع الاتزان، وتدل على الطاقة', 'العلاقة الأساسية: v = f λ']::text[], ARRAY['عند ضبط محطة راديو على تردد معيّن فأنت تختار موجة بطول موجي محدد.', 'موجة سرعتها 340 م/ث وترددها 170 هرتز طولها الموجي 2 متر (λ = v ÷ f).']::text[], ARRAY['الخلط بين السعة والطول الموجي، والصحيح أن السعة رأسية (طاقة) والطول الموجي أفقي (مسافة).', 'اعتقاد أن زيادة التردد تزيد السرعة دائمًا، والصحيح أن السرعة تحددها خصائص الوسط.']::text[], 'approved', 'curriculum_seed', false),
  ('g10-phy-waves-l3', 'g10-phy-waves-unit', 'الموجات الصوتية', 3, 'الصوت موجة ميكانيكية طولية تنتج عن اهتزاز الأجسام، وتحتاج وسطًا ماديًا لتنتقل، لذلك لا ينتقل الصوت في الفراغ. تختلف سرعة الصوت باختلاف الوسط، فهي أكبر في المواد الصلبة منها في السوائل، وأكبر في السوائل منها في الغازات، لأن ترابط الجزيئات أقوى في الصلب. ويوصف الصوت بصفتين: الشدة (العلو) وترتبط بالسعة، وطبقة الصوت (الحدّة) وترتبط بالتردد.', ARRAY['الصوت موجة ميكانيكية طولية', 'الصوت لا ينتقل في الفراغ', 'سرعة الصوت: صلب > سائل > غاز', 'الشدة (العلو) ترتبط بالسعة', 'طبقة الصوت (الحدّة) ترتبط بالتردد']::text[], ARRAY['لا يُسمع انفجار في الفضاء لأن لا وسط مادي ينقل الصوت.', 'ينتقل الصوت في الحديد أسرع من انتقاله في الهواء بكثير.', 'صوت الطفل أعلى حدّة (طبقة) من صوت الرجل لأن تردده أعلى.']::text[], ARRAY['اعتقاد أن الصوت ينتقل في الفراغ مثل الضوء، والصحيح أنه يحتاج وسطًا ماديًا.', 'الخلط بين شدة الصوت وحدّته، والصحيح أن الشدة من السعة والحدّة من التردد.']::text[], 'draft', 'curriculum_seed', false),
  ('g10-phy-waves-l4', 'g10-phy-waves-unit', 'سلوك الموجات', 4, 'تُظهر الموجات سلوكيات مميزة عند تفاعلها مع الأوساط أو مع بعضها. فالانعكاس هو ارتداد الموجة عند اصطدامها بحاجز، والانكسار هو تغيّر اتجاه الموجة عند انتقالها بين وسطين مختلفين بسبب تغيّر سرعتها. وعند التقاء موجتين يحدث التداخل: إذا التقت قمة مع قمة تعزّزت الموجة (تداخل بنّاء)، وإذا التقت قمة مع قاع تلاشت أو ضعُفت (تداخل هدّام).', ARRAY['الانعكاس: ارتداد الموجة عن حاجز', 'الانكسار: تغيّر الاتجاه بسبب تغيّر السرعة بين وسطين', 'التداخل البنّاء: قمة + قمة → تعزيز', 'التداخل الهدّام: قمة + قاع → إضعاف']::text[], ARRAY['صدى الصوت في الوادي مثال على انعكاس الموجات الصوتية.', 'ظهور القلم مكسورًا في كأس ماء مثال على انكسار الضوء.', 'تعزّز الصوت في بعض مواضع القاعة وخفوته في مواضع أخرى مثال على التداخل.']::text[], ARRAY['اعتقاد أن الانكسار يعني انكسار الموجة فيزيائيًا، والصحيح أنه تغيّر في اتجاه انتشارها.', 'اعتقاد أن التداخل الهدّام يُفني الطاقة، والصحيح أنها تُعاد توزيعًا لا تُفنى.']::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u1-l1', 'g9-phy-s1-u1-length-time', '1-1 أهمية القياس', 1, 'اتُّفق دوليًا على تعريف وحدات القياس الأساسية وتوحيدها حتى تكون القياسات قابلة للمقارنة والفهم. وتوضح تطبيقات الملاحة بالأقمار الصناعية أن القياس الدقيق للزمن قد يكون حاسمًا في تحديد الموقع.', ARRAY['وحدات القياس الأساسية يجب أن تكون معرّفة وموحّدة دوليًا.', 'استخدام نظام وحدات متفق عليه يسهّل مقارنة القياسات ومشاركة البيانات وفهمها.', 'الدقة في القياس قد تكون مهمة جدًا حتى عندما يكون مقدار الخطأ صغيرًا للغاية.', 'في النظام الدولي للوحدات: وحدة الطول الأساسية هي المتر (m)، وألف متر يساوي كيلومترًا واحدًا (km)، وجزء من ألف من المتر يساوي مليمترًا واحدًا (mm).']::text[], ARRAY['يعتمد جهاز الملاحة المتصل بالأقمار الصناعية على قياس زمن وصول الإشارات بدقة شديدة لتحديد الموقع.', 'نستخدم القياس في المنزل والطهي والرياضة والطب والهندسة والملاحة وغيرها من مجالات الحياة.', 'تظهر الحاجة إلى وحدات قياس مشتركة في مجالات مثل الطب والهندسة والعمارة ومسح الكميات والعقارات والملاحة.']::text[], ARRAY['الجهاز الرقمي ليس بالضرورة أكثر دقة من الجهاز التناظري؛ فكلاهما يعتمد على مبدأ القياس نفسه، بينما قد تسهّل الشاشة الرقمية عملية القراءة.']::text[], 'approved', 'curriculum_seed', true),
  ('g9-phy-s1-u1-l2', 'g9-phy-s1-u1-length-time', '1-2 قياس الطول والحجم', 2, 'القياس الجيد لا يعتمد على الأداة وحدها؛ بل على اختيار أداة ومدى مناسبين، ومحاذاة الجسم والقراءة بطريقة صحيحة. تستخدم المسطرة للأطوال المناسبة، والميكرومتر للأبعاد الصغيرة جدًا، والمخبار المدرج لقياس حجم السوائل، ويمكن إيجاد حجم الجسم غير المنتظم بطريقة الإزاحة.', ARRAY['عند القياس بالمسطرة يُحاذى الجسم مع التدريج وتوضع بداية القياس عند الصفر وتُقرأ النهاية بوضوح.', 'يمكن قياس بعد صغير جدًا بصورة غير مباشرة بقياس مجموعة من الأجسام المتماثلة ثم القسمة على عددها.', 'يستخدم الميكرومتر لقياس أبعاد صغيرة جدًا، وتجمع قراءة التدريج الرئيسي مع قراءة التدريج الكسري.', 'حجم متوازي المستطيلات يساوي الطول × العرض × الارتفاع.', 'يقاس حجم السائل بالمخبار المدرج المناسب، وتؤخذ قراءة الماء عند أسفل السطح المقعر وبمستوى نظر أفقي.', 'يُقاس حجم الجسم غير المنتظم بطريقة الإزاحة، ويساوي قراءة مستوى الماء بعد الغمر ناقص قراءة مستوى الماء قبل الغمر.']::text[], ARRAY['يمكن قياس سمك ورقة واحدة بقياس سمك رزمة من 500 ورقة ثم قسمة السمك الكلي على 500.', 'قراءة ميكرومتر مقدارها 2.5 mm على التدريج الرئيسي و0.17 mm على التدريج الكسري تعطي 2.67 mm.', 'إذا ارتفع الماء في المخبار من 42 mL إلى 57 mL بعد غمر جسم غير منتظم فإن حجم الجسم يساوي 15 mL، أي 15 cm³.']::text[], ARRAY['الاعتقاد أن المسطرة تكفي لقياس كل الأطوال مهما صغر البعد؛ والصحيح أن الأبعاد الصغيرة جدًا قد تحتاج إلى الميكرومتر أو إلى قياس غير مباشر.', 'الاعتقاد أن المخبار الأكبر هو الأفضل دائمًا؛ والصحيح أن اختيار المدى والتدرج يجب أن يناسب مقدار السائل المراد قياسه.', 'الاعتقاد أن قراءة السائل تؤخذ من أي زاوية؛ والصحيح أن قراءة الماء تؤخذ عند أسفل السطح المقعر وبمستوى نظر أفقي.']::text[], 'approved', 'curriculum_seed', true),
  ('g9-phy-s1-u1-l3', 'g9-phy-s1-u1-length-time', '1-3 قياس الزمن', 3, 'تُقاس الفترات الزمنية بساعات وأجهزة تناظرية ورقمية، لكن جودة القياس لا تعتمد على عدد المنازل المعروضة وحده. عند قياس الفترات القصيرة يمكن أن يؤثر زمن استجابة الإنسان، ويمكن تحسين القياس بتكراره أو بقياس عدد من الأحداث الدورية ثم حساب متوسط زمن الحدث الواحد.', ARRAY['يختلف مستوى التفصيل المطلوب في قياس الزمن بحسب الموقف الذي نريد دراسته.', 'تُقرأ ساعة الإيقاف التناظرية من تدريجها، بينما تعطي الساعة الرقمية قراءة مباشرة بالأرقام.', 'قد تعرض الساعة الرقمية أجزاء صغيرة جدًا من الثانية، لكن القياس اليدوي يظل متأثرًا بزمن استجابة الإنسان.', 'يمكن توقع لحظة بدء حدث دوري واستخدام العد التنازلي لتحسين بدء التوقيت.', 'الزمن الدوري للبندول هو زمن تأرجح كامل واحد يعود فيه البندول إلى حالة البداية.', 'يمكن قياس زمن عدد من التأرجحات الكاملة ثم قسمة الزمن الكلي على عددها لإيجاد متوسط زمن التأرجح الواحد.']::text[], ARRAY['في سباق قصير قد تفصل أجزاء صغيرة من الثانية بين المراكز، بينما يمكن في حدث طويل تسجيل الزمن بأقل تفصيل.', 'الفترة 2 min 14.37 s تظهر على تدريج يسمح بأقرب 0.1 s بصورة تقارب 2 min 14.4 s.', 'إذا استغرقت 12 تأرجحًا كاملًا 14.76 s فإن متوسط زمن التأرجح الواحد يساوي 1.23 s.']::text[], ARRAY['الاعتقاد أن عرض الساعة الرقمية منزلتين عشريتين يعني أن القياس اليدوي نفسه دقيق إلى 0.01 s؛ والصحيح أن زمن استجابة الإنسان قد يحد جودة القياس الفعلي.']::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u2-l1', 'g9-phy-s1-u2-motion', '2-1 فهم السرعة', 1, 'المحتوى التعليمي لهذا الدرس قيد الإعداد والمراجعة قبل النشر للطلبة.', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u2-l2', 'g9-phy-s1-u2-motion', '2-2 التمثيل البياني (المسافة/الزمن)', 2, 'المحتوى التعليمي لهذا الدرس قيد الإعداد والمراجعة قبل النشر للطلبة.', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u2-l3', 'g9-phy-s1-u2-motion', '2-3 فهم التسارع', 3, 'المحتوى التعليمي لهذا الدرس قيد الإعداد والمراجعة قبل النشر للطلبة.', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u2-l4', 'g9-phy-s1-u2-motion', '2-4 حساب السرعة والتسارع', 4, 'المحتوى التعليمي لهذا الدرس قيد الإعداد والمراجعة قبل النشر للطلبة.', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u3-l1', 'g9-phy-s1-u3-mass-weight', '3-1 الكتلة والوزن والجاذبية', 1, 'المحتوى التعليمي لهذا الدرس قيد الإعداد والمراجعة قبل النشر للطلبة.', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], 'draft', 'curriculum_seed', false),
  ('g9-phy-s1-u4-l1', 'g9-phy-s1-u4-density', '4-1 الكثافة', 1, 'المحتوى التعليمي لهذا الدرس قيد الإعداد والمراجعة قبل النشر للطلبة.', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], 'draft', 'curriculum_seed', false),
