VALUES
  ('l1-rq1', 'g10-phy-waves-l1', 'review', 'multiple_choice', 'ما الذي تنقله الموجة أساسًا من مكان إلى آخر؟', ARRAY['المادة', 'الطاقة', 'الوسط', 'الجزيئات']::text[], 1, 'الموجة تنقل الطاقة دون أن تنقل معها مادة الوسط نفسه.', 'l1-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l1-rq2', 'g10-phy-waves-l1', 'review', 'multiple_choice', 'أي الموجات التالية تحتاج وسطًا ماديًا لتنتقل؟', ARRAY['الضوء', 'موجات الراديو', 'الصوت', 'الأشعة السينية']::text[], 2, 'الصوت موجة ميكانيكية تحتاج وسطًا ماديًا، بخلاف الموجات الكهرومغناطيسية.', 'l1-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l1-rq3', 'g10-phy-waves-l1', 'review', 'multiple_choice', 'في الموجة الطولية يكون اهتزاز جزيئات الوسط:', ARRAY['عموديًا على اتجاه الانتشار', 'في اتجاه الانتشار نفسه', 'دائريًا حول مركز ثابت', 'بلا اهتزاز']::text[], 1, 'في الموجة الطولية يهتز الوسط موازيًا لاتجاه انتشار الموجة.', 'l1-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l1-rq4', 'g10-phy-waves-l1', 'review', 'multiple_choice', 'أي مما يلي مثال على موجة كهرومغناطيسية؟', ARRAY['موجات الماء', 'الصوت', 'الضوء', 'موجة في حبل']::text[], 2, 'الضوء موجة كهرومغناطيسية تنتقل حتى في الفراغ.', 'l1-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l1-rq5', 'g10-phy-waves-l1', 'review', 'multiple_choice', 'تموّج حبل مربوط عند هزّه لأعلى وأسفل يمثّل موجة:', ARRAY['طولية', 'عرضية', 'كهرومغناطيسية', 'صوتية']::text[], 1, 'اهتزاز الحبل عمودي على اتجاه انتشار الموجة، فهي موجة عرضية.', 'l1-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l1-rq6', 'g10-phy-waves-l1', 'review', 'multiple_choice', 'لماذا تصل أشعة الشمس إلى الأرض عبر الفضاء؟', ARRAY['لأنها موجة ميكانيكية سريعة', 'لأنها موجة كهرومغناطيسية لا تحتاج وسطًا', 'لأن الفضاء مملوء بالهواء', 'لأنها تنقل المادة معها']::text[], 1, 'الضوء موجة كهرومغناطيسية تنتقل في الفراغ دون حاجة إلى وسط مادي.', 'l1-o1', 'medium', 'draft', 'curriculum_seed'),
  ('l2-rq1', 'g10-phy-waves-l2', 'review', 'multiple_choice', 'الطول الموجي هو المسافة بين:', ARRAY['قمة وقاع متتاليين', 'قمتين متتاليتين', 'قاعين بينهما قمتان', 'بداية ونهاية الاهتزاز']::text[], 1, 'الطول الموجي هو المسافة بين قمتين متتاليتين (أو قاعين متتاليين).', 'l2-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l2-rq2', 'g10-phy-waves-l2', 'review', 'multiple_choice', 'وحدة قياس التردد هي:', ARRAY['المتر', 'الثانية', 'الهرتز', 'النيوتن']::text[], 2, 'التردد يُقاس بالهرتز (Hz)، أي عدد الموجات في الثانية.', 'l2-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l2-rq3', 'g10-phy-waves-l2', 'review', 'multiple_choice', 'أي مقدار يدل على طاقة الموجة؟', ARRAY['الطول الموجي', 'التردد', 'السعة', 'السرعة']::text[], 2, 'السعة (أقصى إزاحة عن وضع الاتزان) تدل على طاقة الموجة.', 'l2-o1', 'medium', 'draft', 'curriculum_seed'),
  ('l2-rq4', 'g10-phy-waves-l2', 'review', 'multiple_choice', 'موجة ترددها 50 هرتز وطولها الموجي 4 أمتار، ما سرعتها؟', ARRAY['12.5 م/ث', '54 م/ث', '200 م/ث', '0.08 م/ث']::text[], 2, 'v = f λ = 50 × 4 = 200 م/ث.', 'l2-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l2-rq5', 'g10-phy-waves-l2', 'review', 'multiple_choice', 'عند ثبات سرعة الموجة، إذا زاد ترددها فإن طولها الموجي:', ARRAY['يزداد', 'يقصُر', 'يبقى ثابتًا', 'ينعدم']::text[], 1, 'من العلاقة v = f λ، عند ثبات v تكون f و λ متناسبتين عكسيًا.', 'l2-o2', 'hard', 'draft', 'curriculum_seed'),
  ('l2-rq6', 'g10-phy-waves-l2', 'review', 'multiple_choice', 'موجة سرعتها 340 م/ث وترددها 170 هرتز، ما طولها الموجي؟', ARRAY['2 متر', '0.5 متر', '510 متر', '57800 متر']::text[], 0, 'λ = v ÷ f = 340 ÷ 170 = 2 متر.', 'l2-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l3-rq1', 'g10-phy-waves-l3', 'review', 'multiple_choice', 'الصوت من حيث النوع موجة:', ARRAY['كهرومغناطيسية عرضية', 'ميكانيكية طولية', 'ميكانيكية عرضية', 'كهرومغناطيسية طولية']::text[], 1, 'الصوت موجة ميكانيكية طولية تحتاج وسطًا ماديًا.', 'l3-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l3-rq2', 'g10-phy-waves-l3', 'review', 'multiple_choice', 'لماذا لا يُسمع الصوت في الفضاء الخارجي؟', ARRAY['لأن الصوت ضعيف هناك', 'لعدم وجود وسط مادي ينقله', 'لأن السرعة عالية جدًا', 'بسبب انعدام الجاذبية']::text[], 1, 'الفضاء فراغ لا يحوي وسطًا ماديًا، والصوت يحتاج وسطًا لينتقل.', 'l3-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l3-rq3', 'g10-phy-waves-l3', 'review', 'multiple_choice', 'في أي وسط ينتقل الصوت بأكبر سرعة؟', ARRAY['الهواء', 'الماء', 'الحديد', 'الفراغ']::text[], 2, 'سرعة الصوت أكبر في الصلب لأن ترابط جزيئاته أقوى.', 'l3-o1', 'medium', 'draft', 'curriculum_seed'),
  ('l3-rq4', 'g10-phy-waves-l3', 'review', 'multiple_choice', 'شدة الصوت (علوّه) ترتبط بأي خاصية للموجة؟', ARRAY['التردد', 'السعة', 'الطول الموجي', 'السرعة']::text[], 1, 'شدة الصوت (العلو) ترتبط بسعة الموجة.', 'l3-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l3-rq5', 'g10-phy-waves-l3', 'review', 'multiple_choice', 'طبقة الصوت (حدّته) ترتبط بأي خاصية للموجة؟', ARRAY['السعة', 'التردد', 'الطاقة', 'الشدة']::text[], 1, 'طبقة الصوت (الحدّة) ترتبط بتردد الموجة؛ كلما زاد التردد زادت الحدّة.', 'l3-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l3-rq6', 'g10-phy-waves-l3', 'review', 'multiple_choice', 'صوت طفل أعلى حدّة من صوت رجل، ما السبب؟', ARRAY['سعة صوت الطفل أكبر', 'تردد صوت الطفل أعلى', 'صوت الطفل أشد', 'طول موجة صوت الطفل أكبر']::text[], 1, 'الحدّة (الطبقة) ترتبط بالتردد، وتردد صوت الطفل أعلى.', 'l3-o2', 'hard', 'draft', 'curriculum_seed'),
  ('l4-rq1', 'g10-phy-waves-l4', 'review', 'multiple_choice', 'ارتداد الموجة عند اصطدامها بحاجز يسمى:', ARRAY['الانكسار', 'الانعكاس', 'التداخل', 'الحيود']::text[], 1, 'الانعكاس هو ارتداد الموجة عند اصطدامها بحاجز.', 'l4-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l4-rq2', 'g10-phy-waves-l4', 'review', 'multiple_choice', 'صدى الصوت في الوادي مثال على:', ARRAY['الانكسار', 'الانعكاس', 'التداخل الهدّام', 'السعة']::text[], 1, 'الصدى ناتج عن انعكاس الموجات الصوتية عن حاجز.', 'l4-o1', 'easy', 'draft', 'curriculum_seed'),
  ('l4-rq3', 'g10-phy-waves-l4', 'review', 'multiple_choice', 'تغيّر اتجاه الموجة عند انتقالها بين وسطين مختلفين يسمى:', ARRAY['الانعكاس', 'الانكسار', 'التداخل', 'الاهتزاز']::text[], 1, 'الانكسار هو تغيّر اتجاه الموجة بسبب تغيّر سرعتها بين وسطين.', 'l4-o1', 'medium', 'draft', 'curriculum_seed'),
  ('l4-rq4', 'g10-phy-waves-l4', 'review', 'multiple_choice', 'ظهور القلم مكسورًا داخل كأس ماء مثال على:', ARRAY['الانعكاس', 'الانكسار', 'التداخل البنّاء', 'الصدى']::text[], 1, 'هذا انكسار للضوء عند انتقاله بين الهواء والماء.', 'l4-o1', 'medium', 'draft', 'curriculum_seed'),
  ('l4-rq5', 'g10-phy-waves-l4', 'review', 'multiple_choice', 'عند التقاء قمة موجة مع قمة موجة أخرى يحدث تداخل:', ARRAY['هدّام', 'بنّاء', 'معدوم', 'انكساري']::text[], 1, 'التقاء قمة مع قمة يعزّز الموجة، وهو تداخل بنّاء.', 'l4-o2', 'medium', 'draft', 'curriculum_seed'),
  ('l4-rq6', 'g10-phy-waves-l4', 'review', 'multiple_choice', 'عند التقاء قمة موجة مع قاع موجة أخرى مماثلة يحدث:', ARRAY['تعزيز الموجة', 'إضعاف أو تلاشي الموجة', 'زيادة التردد', 'انعكاس']::text[], 1, 'التقاء قمة مع قاع يُضعف الموجة أو يُلاشيها، وهو تداخل هدّام.', 'l4-o2', 'hard', 'draft', 'curriculum_seed'),
  ('g9-s1-u1-l1-rq1', 'g9-phy-s1-u1-l1', 'review', 'multiple_choice', 'في نظام وحدات متفق عليه بين العلماء، ما وحدة SI الأساسية لقياس الطول؟', ARRAY['المتر (m)', 'اللتر (L)', 'الثانية (s)', 'الكيلوغرام (kg)']::text[], 0, 'المتر (m) هو وحدة النظام الدولي الأساسية للطول.', 'g9-s1-u1-l1-o1', 'easy', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l1-rq2', 'g9-phy-s1-u1-l1', 'review', 'multiple_choice', 'قاس طالب مسافة مقدارها 3000 m. ما القيمة المكافئة لها؟', ARRAY['3 km', '30 km', '300 km', '0.3 km']::text[], 0, 'كل 1000 m تساوي 1 km، لذلك 3000 m تساوي 3 km.', 'g9-s1-u1-l1-o1', 'medium', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l1-rq3', 'g9-phy-s1-u1-l1', 'review', 'multiple_choice', 'انظر إلى سجل القياس المصور: طول قلم = 25 من دون وحدة. أي وحدة تكمل التسجيل بصورة مناسبة؟', ARRAY['cm', 'L', 's', 'kg']::text[], 0, 'تسجيل الطول يحتاج قيمة عددية ووحدة طول مناسبة؛ 25 cm تسجيل مكتمل وواضح.', 'g9-s1-u1-l1-o1', 'medium', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l1-rq4', 'g9-phy-s1-u1-l1', 'review', 'multiple_choice', 'عرض جهاز رقمي قراءة 12.345 cm، بينما عرض جهاز تناظري 12.3 cm. أي حكم أدق؟', ARRAY['لا يمكن الحكم على الدقة من عدد الأرقام المعروضة وحده', 'الجهاز الرقمي أدق دائمًا لأنه يعرض أرقامًا أكثر', 'الجهاز التناظري أدق دائمًا لأنه لا يستخدم شاشة', 'القراءتان غير قابلتين للمقارنة لأن شكل الجهازين مختلف']::text[], 0, 'عدد الخانات الظاهرة لا يكفي للحكم على الدقة؛ تتأثر جودة القياس بالأداة وطريقة الاستخدام وحدود القياس.', 'g9-s1-u1-l1-o1', 'hard', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l1-rq5', 'g9-phy-s1-u1-l1', 'review', 'multiple_choice', 'يريد مختبران في بلدين مختلفين مقارنة قياسات طول للجسم نفسه. ما الإجراء الأهم قبل مقارنة النتائج؟', ARRAY['استخدام نظام وحدات متفق عليه أو تحويل القياسات إلى وحدة مشتركة', 'جمع جميع القيم حتى لو كانت بوحدات مختلفة', 'اختيار أكبر قيمة فقط', 'إهمال الوحدات والاكتفاء بالأرقام']::text[], 0, 'توحيد الوحدة أو استخدام نظام قياس مشترك يجعل البيانات قابلة للفهم والمقارنة بين الفرق المختلفة.', 'g9-s1-u1-l1-o1', 'hard', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l2-rq1', 'g9-phy-s1-u1-l2', 'review', 'multiple_choice', 'أي أداة تختار لقياس قطر سلك نحاسي رفيع جدًا؟', ARRAY['مسطرة', 'ميكرومتر', 'مخبار مدرج']::text[], 1, 'الميكرومتر مناسب لقياس قطر السلك لأن هذا البعد صغير جدًا مقارنة بما يمكن قراءته بوضوح على المسطرة.', 'g9-s1-u1-l2-o4', 'easy', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l2-rq2', 'g9-phy-s1-u1-l2', 'review', 'multiple_choice', 'قِيس سمك 100 ورقة متماثلة معًا فكان 8.0 mm. ما سمك ورقة واحدة؟', ARRAY['0.08 mm', '0.8 mm', '8 mm', '80 mm']::text[], 0, 'القياس 8.0 mm يخص 100 ورقة؛ لذلك نقسمه على 100 فنحصل على 0.08 mm لسمك ورقة واحدة.', 'g9-s1-u1-l2-o1', 'medium', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l2-rq3', 'g9-phy-s1-u1-l2', 'review', 'multiple_choice', 'اقرأ الميكرومتر: التدريج الرئيسي يصل إلى 3.00 mm، وخط المرجع يطابق 28 تقسيمًا من 0.01 mm. ما القراءة النهائية؟', ARRAY['3.28 mm', '3.028 mm', '3.00 mm', '0.28 mm']::text[], 0, 'التدريج الرئيسي 3.00 mm، والتدريج الكسري 28 × 0.01 mm = 0.28 mm؛ إذن القراءة الكلية 3.28 mm.', 'g9-s1-u1-l2-o4', 'medium', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l2-rq4', 'g9-phy-s1-u1-l2', 'review', 'multiple_choice', 'يريد طالب قياس 6 mL بمخبار سعته 1000 mL وأصغر تقسيم فيه 10 mL. ما المشكلة في خطة القياس؟', ARRAY['التدرج لا يسمح بقراءة 6 mL مباشرة، ونحتاج مدى وتدرجًا أنسب للكمية', 'موضع النظر وحده هو المشكلة، والمخبار مناسب كما هو', 'وحدة mL غير مناسبة لقياس حجم السوائل']::text[], 0, 'عندما يكون أصغر تقسيم 10 mL فإن 6 mL تقع بين علامتين ولا يمكن قراءتها مباشرة من التدريج؛ نختار مخبارًا بمدى وتدرج يناسبان الكمية الصغيرة.', 'g9-s1-u1-l2-o1', 'hard', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l2-rq5', 'g9-phy-s1-u1-l2', 'review', 'multiple_choice', 'مسار سلكي منحني مثبّت على لوحة ولا يمكن فرده أو تغيير شكله. كيف تقيس طول المسار من بدايته إلى نهايته؟', ARRAY['أتتبع المسار بخيط مرن ثم أفرد الجزء المحدد من الخيط على المسطرة', 'أحاول فرد المسار المثبّت بالقوة ثم أقيسه بالمسطرة', 'أستخدم الميكرومتر لقياس طول المسار كله']::text[], 0, 'لأن المسار مثبت ولا يمكن تقويمه، نتتبعه بخيط مرن من البداية إلى النهاية، نحدد هذا الجزء من الخيط، ثم نفرده على المسطرة لقياس طوله.', 'g9-s1-u1-l2-o1', 'hard', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l3-rq1', 'g9-phy-s1-u1-l3', 'review', 'multiple_choice', 'عند قياس فترة زمنية لحدث، ماذا تمثل هذه الفترة؟', ARRAY['الزمن الممتد من بداية الحدث إلى نهايته', 'قراءة بداية الحدث وحدها', 'قراءة نهاية الحدث وحدها', 'عدد المنازل العشرية التي تعرضها الساعة']::text[], 0, 'الفترة الزمنية تمتد من بداية الحدث إلى نهايته، وهي مقدار زمني لا قراءة منفردة عند البداية أو النهاية.', 'g9-s1-u1-l3-o2', 'easy', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l3-rq2', 'g9-phy-s1-u1-l3', 'review', 'multiple_choice', 'يعرض التلفاز 25 صورة كل ثانية. ما الزمن بين صورتين متتاليتين؟', ARRAY['0.04 ثانية', '0.25 ثانية', '4 ثوانٍ', '25 ثانية']::text[], 0, 'زمن الصورة الواحدة = 1 ÷ 25 = 0.04 ثانية.', 'g9-s1-u1-l3-o2', 'medium', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l3-rq3', 'g9-phy-s1-u1-l3', 'review', 'multiple_choice', 'أُعيد قياس فترة زمنية ثلاث مرات: 0.82، 0.84، 0.92 ثانية. ما القيمة المتوسطة للقياسات؟', ARRAY['0.86 ثانية', '0.84 ثانية', '0.92 ثانية', '0.82 ثانية']::text[], 0, 'القيمة المتوسطة = (0.82 + 0.84 + 0.92) ÷ 3 = 0.86 ثانية.', 'g9-s1-u1-l3-o3', 'medium', 'approved', 'curriculum_seed'),
  ('g9-s1-u1-l3-rq4', 'g9-phy-s1-u1-l3', 'review', 'multiple_choice', 'قال طالب: «انتقال البندول من نقطة البداية إلى الطرف المقابل يمثل تأرجحًا كاملًا». ما التصحيح العلمي؟', ARRAY['هذا نصف تأرجح؛ التأرجح الكامل ينتهي عندما يعود البندول إلى نقطة البداية', 'هذا تأرجح كامل فعلًا؛ لا حاجة إلى العودة إلى نقطة البداية', 'التأرجح الكامل هو المرور بنقطة الاتزان مرة واحدة فقط', 'لا يمكن تعريف التأرجح الكامل باستخدام موضع البداية']::text[], 0, 'الانتقال إلى الطرف المقابل لا يكمل دورة كاملة؛ يكتمل التأرجح عندما يعود البندول إلى حالة البداية.', 'g9-s1-u1-l3-o3', 'medium', 'approved', 'curriculum_seed'),
